def icon(name, size=22, cls="ph", label=None):
    """One Phosphor mark, inline. `label` (already escaped by the caller or
    plain text) makes it a labelled image; without one it is decoration and
    hidden from assistive tech, so the control it sits in must carry the
    words — every tile and button on the home does."""
    d = PATHS[name]
    if label:
        return (f'<svg class="{cls}" role="img" aria-label="{_esc(label, quote=True)}" width="{size}" '
                f'height="{size}" viewBox="0 0 256 256" fill="currentColor"><path d="{d}"/></svg>')
    return (f'<svg class="{cls}" aria-hidden="true" focusable="false" width="{size}" height="{size}" '
            f'viewBox="0 0 256 256" fill="currentColor"><path d="{d}"/></svg>')
